import { and, eq, isNull, or } from \"drizzle-orm\";
import { OwnershipHandoverError } from \"@/lib/errors\";
import { newId } from \"@/lib/id\";
import { PermissionDeniedError } from \"@/lib/permissions\";
import { getDb, members, notifications, organizations, ownershipHandovers } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import { NotFoundError } from \"@/server/services/_support\";
import { brandId, brandStamp, brandStampOrNull, toOrganization } from \"./_mappers\";
import type { OwnershipHandoverRow } from \"@/server/db\";
import type { OrgId, UserId } from \"@/types/common\";
import type { Actor, Role } from \"@/types/member\";
import type { OwnershipHandover } from \"@/types/organization\";

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id, orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId), toUserId: brandId<UserId>(row.toUserId),
    status: row.status, expiresAt: brandStamp(row.expiresAt), createdAt: brandStamp(row.createdAt),
    resolvedAt: brandStampOrNull(row.resolvedAt),
  };
}

function denyOwner(): never {
  throw new PermissionDeniedError(\"org:update\", {
    action: \"org:update\", resourceKind: \"organization\", allowed: false, reason: \"denied_by_role\",
  });
}

type Tx = Parameters<Parameters<ReturnType<typeof getDb>[\"transaction\"]>[0]>[0];
function orgAndOwner(tx: Tx, actor: Actor, orgId: OrgId) {
  const org = tx.select().from(organizations).where(eq(organizations.id, orgId)).get();
  if ("'!org) throw new NotFoundError("Organization", orgId);
  if (org.ownerId !== actor.userId) denyOwner();
  return org;
}
function pending(tx: Tx, orgId: OrgId) {
  return tx.select().from(ownershipHandovers).where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"))).get();
}

export function initiate(actor: Actor, orgId: OrgId, toUserId: UserId): OwnershipHandover {
  return getDb().transaction((tx) => {
    orgAndOwner(tx, actor, orgId);
    if (toUserId === actor.userId) throw new OwnershipHandoverError("self");
    const target = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, toUserId), eq(members.status, "active"), isNull(members.archivedAt))).get();
    if (!target) throw new NotFoundError("Member", toUserId);
    const now = toIsoTimestamp(new Date());
    const existing = pending(tx, orgId);
    if (existing && existing.expiresAt > now) throw new OwnershipHandoverError("pending_exists");
    if (existing) tx.update(ownershipHandovers).set({ status: "expired", resolvedAt: existing.expiresAt }).where(eq(ownershipHandovers.id, existing.id)).run();
    const row = tx.insert(ownershipHandovers).values({
      id: newId(), orgId, fromUserId: actor.userId, toUserId, status: "pending", createdAt: now,
      expiresAt: toIsoTimestamp(new Date(new Date(now).getTime() + 7 * 24 * 60 * 60 * 1000)), resolvedAt: null,
    }).returning().get();
    tx.insert(notifications).values({
      id: newId(), orgId, recipientId: toUserId, kind: "ownership_handover",
      title: "Workspace ownership offered", body: "You have been invited to accept ownership of this workspace.",
      href: "/settings/members", actorId: actor.userId, channels: JSON.stringify(["in_app", "email"]),
      readAt: null, createdAt: now, updatedAt: now,
    }).run();
    return toHandover(row);
  });
}

export function getPending(orgId: OrgId): OwnershipHandover | null {
  const row = pending(getDb(), orgId);
  return row && row.expiresAt > toIsoTimestamp(new Date()) ? toHandover(row) : null;
}

export function resolve(actor: Actor, orgId: OrgId, action: "accepted" | "declined" | "canceled") {
  return getDb().transaction((tx) => {
    if (action === "canceled") orgAndOwner(tx, actor, orgId);
    const row = pending(tx, orgId);
    if (!row || (action !== "canceled" && row.toUserId !== actor.userId)) throw new OwnershipHandoverError("nothing_pending");
    const now = toIsoTimestamp(new Date());
    if (row.expiresAt <= now) throw new OwnershipHandoverError(action === "canceled" ? "nothing_pending" : "expired");
    const changes: { memberId: string; from: Role; to: Role }[] = [];
    let organization = null;
    if (action === "accepted") {
      const target = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, row.toUserId), eq(members.status, "active"), isNull(members.archivedAt))).get();
      const source = tx.select().from(members).where(and(eq(members.orgId, orgId), eq(members.userId, row.fromUserId), eq(members.status, "active"), isNull(members.archivedAt))).get();
      if (!target || !source) throw new OwnershipHandoverError("nothing_pending");
      if (target.role !== "owner") {
        tx.update(members).set({ role: "owner", updatedAt: now }).where(eq(members.id, target.id)).run();
        changes.push({ memberId: target.id, from: target.role, to: "owner" });
      }
      if (source.role === "owner") {
        tx.update(members).set({ role: "admin", updatedAt: now }).where(eq(members.id, source.id)).run();
        changes.push({ memberId: source.id, from: "owner", to: "admin" });
      }
      const updated = tx.update(organizations).set({ ownerId: row.toUserId, updatedAt: now }).where(and(eq(organizations.id, orgId), eq(organizations.ownerId, row.fromUserId))).returning().get();
      if (!updated) throw new OwnershipHandoverError("nothing_pending");
      organization = toOrganization(updated);
    }
    const resolved = tx.update(ownershipHandovers).set({ status: action, resolvedAt: now }).where(eq(ownershipHandovers.id, row.id)).returning().get();
    return { handover: toHandover(resolved), organization, changes };
  });
}

/** Called in the same transaction as a membership removal. */
export function cancelForMember(tx: Tx, orgId: OrgId, userId: UserId, now: string): void {
  tx.update(ownershipHandovers).set({ status: "canceled", resolvedAt: now }).where(and(
    eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"),
    or(eq(ownershipHandovers.fromUserId, userId), eq(ownershipHandovers.toUserId, userId)),
  )).run();
}
